import{_ as i,a0 as d,w as s,s as r,I as t,x as l,a1 as o,A as p,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const O=JSON.parse('{"title":"OpenBSD 7.3 發佈，包含新功能和更新 | LCTT x X-CMD","titleTemplate":false,"description":"OpenBSD 7.3 發佈，包含新功能和更新 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OpenBSD 7.3 發佈，包含新功能和更新 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OpenBSD 7.3 發佈，包含新功能和更新 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230412.1 ⭐️⭐️ OpenBSD 7.3 Released with New Features and Updates","title":"OpenBSD 7.3 發佈，包含新功能和更新","tag":"202304","desc":""},"relativePath":"202304/20230412.1 ⭐️⭐️ OpenBSD 7.3 Released with New Features and Updates.md","filePath":"[post].md"}'),u={name:"202304/20230412.1 ⭐️⭐️ OpenBSD 7.3 Released with New Features and Updates.md"};function m(D,e,f,g,S,w){const n=d("Link");return s(),r("div",null,[e[20]||(e[20]=t("h1",{id:"openbsd-7-3-發佈-包含新功能和更新",tabindex:"-1"},[l("OpenBSD 7.3 發佈，包含新功能和更新 "),t("a",{class:"header-anchor",href:"#openbsd-7-3-發佈-包含新功能和更新","aria-label":"Permalink to “OpenBSD 7.3 發佈，包含新功能和更新”"},"​")],-1)),e[21]||(e[21]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/16/150654wtvhflqgvmfdg6hv.jpg",alt:""})],-1)),e[22]||(e[22]=t("blockquote",null,[t("p",null,"OpenBSD 7.3 正式發佈，有大量的軟件包更新和改進。")],-1)),e[23]||(e[23]=t("p",null,[t("img",{src:"https://debugpointnews.com/wp-content/uploads/2023/04/OpenBSD-desktop-7-fvwm.jpg",alt:"OpenBSD desktop (7+) fvwm"})],-1)),t("p",null,[e[1]||(e[1]=l("OpenBSD 7.3 已經正式 ",-1)),o(n,{href:"https://www.openbsd.org/73.html"},{default:p(()=>[...e[0]||(e[0]=[l("發佈",-1)])]),_:1}),e[2]||(e[2]=l("，這是該系統的第 54 個版本。這個最新的版本建立在 OpenBSD 令人印象深刻的傲人記錄之上 —— 它是一個安全可靠的操作系統，在二十多年的使用過程中，在默認安裝中只發現了兩個遠程漏洞。",-1))]),e[24]||(e[24]=a('<p>與以前的版本一樣，OpenBSD 7.3 在廣泛的系統領域提供了顯著的改進。其中包括內核的改進，如增加了 <code>waitid(2)</code>、<code>pinsyscall(2)</code>、 <code>getthrname(2)</code> 和 <code>setthrname(2)</code> 函數，以及 <code>waitid(2)</code> 的 <code>WTRAPPED</code> 選項，等等。此外，新的內核 <code>autoconf_serial sysctl(8)</code> 允許用户區監控內核設備樹狀態的變化。</p><p>直接渲染管理器和圖形驅動已經更新，引入了對 Ryzen 7000 “Raphael” 和 Ryzen 7020 和 7045 系列處理器以及 Radeon RX 7900 XT/XTX “Navi 31” 的支持，並改進了蘋果芯片筆記本電腦和聯想 x13s 的問題的解決方案。</p><p>此外，還改進了對網絡硬件的支持，例如啓用了 <code>em(4)</code> IPv4、 TCP 和 UDP 校驗卸載，以及 82575、 82576、 i350 和 i210 芯片組設備上的硬件 VLAN 標記， 以及改進了 <code>mcx(4)</code> 性能。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/04/OpenBSD-7.3-installation.jpg" alt="OpenBSD 7.3 安裝"></p><p>除了上述的改進，OpenBSD 7.3 還包括一系列新的或改進的硬件和軟件對 <ruby>端口源碼包<rt>Port</rt></ruby> 和 <ruby>二進制軟件包<rt>Package</rt></ruby> 的支持。一些來自外部供應商的主要組件包括 Xenocara、LLVM/Clang、GCC、Perl、NSD、Unbound、Ncurses、Binutils、Gdb、Awk 和 Expat。</p><p>OpenBSD 以最安全、最可靠的操作系統之一而聞名。在過去的二十年裏，它的默認安裝中只有兩個遠程漏洞，這一記錄令人印象深刻。隨着 OpenBSD 7.3 的發佈，用户可以期待在幾乎所有的系統領域都有顯著的改進。</p><p>這個版本的內核改進，如增加了 <code>waitid(2)</code>、<code>pinsyscall(2)</code>、<code>getthrname(2)</code>、<code>setthrname(2)</code> 和 <code>clockintr(9)</code>，將為用户提供更簡化的體驗。Direct Rendering Manager 和圖形驅動也得到了更新，包括對 Ryzen 7000 “Raphael”、Radeon RX 7900 XT/XTX “Navi 31” 和 Radeon RX 7600M（XT）等新設備的支持。</p><p>OpenBSD 7.3 還包括改進的網絡硬件支持，在 82575、82576、i350 和 i210 芯片組的設備上啓用 <code>em(4)</code> IPv4、TCP 和 UDP 校驗和卸載以及硬件 VLAN 標記。此外，通過使用基於中斷的命令完成，<code>mcx(4)</code> 的性能得到了提高。</p><p>至於端口源碼包和二進制軟件包，OpenBSD 7.3 包括了最新版本的應用程序、桌面和關鍵軟件包。下面是關鍵端口源碼包和二進制軟件包的新項目列表：</p><p><strong>桌面和應用</strong></p><ul><li>Chromium 111.0.5563.110</li><li>GNOME 43.3</li><li>KDE 應用 22.12.3</li><li>KDE 框架 5.103.0</li><li>Xfce 4.18</li><li>Krita 5.1.5</li><li>LibreOffice 7.5.1.2</li><li>Mozilla Firefox 111.0 和 ESR 102.9.0</li><li>Mozilla Thunderbird 102.9.0</li></ul><p><strong>核心開發軟件包</strong></p><ul><li>Mutt 2.2.9 和 NeoMutt 20220429</li><li>Node.js 18.15.0</li><li>OCaml 4.12.1</li><li>OpenLDAP 2.6.4</li><li>PHP 7.4.33, 8.0.28, 8.1.16 和 8.2.3</li><li>Postfix 3.5.17 和 3.7.3</li><li>PostgreSQL 15.2</li><li>Python 2.7.18, 3.9.16, 3.10.10 和 3.11.2</li><li>Qt 5.15.8 和 6.4.2</li><li>R 4.2.1</li><li>Ruby 3.0.5, 3.1.3 和 3.2.1</li><li>Rust 1.68.0</li><li>Sudo 1.9.13.3</li><li>MariaDB 10.9.4</li><li>Mono 6.12.0.182</li></ul><p>總的來説，最新發布的 OpenBSD 繼續為用户提供安全可靠的操作系統，同時也在系統的各個領域進行了重大改進。我們鼓勵用户升級到 OpenBSD 7.3，以利用這些新功能和改進。</p><p>OpenBSD 7.3 可以從官方網站下載，並有全面的發佈説明，詳細介紹了所有的新功能和改進。</p>',15)),t("blockquote",null,[t("p",null,[t("strong",null,[o(n,{href:"https://cdn.openbsd.org/pub/OpenBSD/7.3/"},{default:p(()=>[...e[3]||(e[3]=[l("下載 OpenBSD 7.3（所有架構）",-1)])]),_:1})])])]),t("blockquote",null,[t("p",null,[t("strong",null,[o(n,{href:"https://www.openbsd.org/plus73.html"},{default:p(()=>[...e[4]||(e[4]=[l("詳細的更新日誌",-1)])]),_:1})])])]),e[25]||(e[25]=t("p",null,[t("em",null,"（題圖： MJ:Future computer with transparent screen, metal box, hd, ultra detailed, sci-fi）")],-1)),e[26]||(e[26]=t("hr",null,null,-1)),t("p",null,[e[6]||(e[6]=l("via: ",-1)),o(n,{href:"https://debugpointnews.com/openbsd-7-3/"},{default:p(()=>[...e[5]||(e[5]=[l("https://debugpointnews.com/openbsd-7-3/",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=l("作者：",-1)),o(n,{href:"https://debugpointnews.com/author/dpicubegmail-com/"},{default:p(()=>[...e[7]||(e[7]=[l("arindam",-1)])]),_:1}),e[12]||(e[12]=l(" 選題：",-1)),o(n,{href:"https://github.com/lkxed/"},{default:p(()=>[...e[8]||(e[8]=[l("lkxed",-1)])]),_:1}),e[13]||(e[13]=l(" 譯者：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[9]||(e[9]=[l("wxy",-1)])]),_:1}),e[14]||(e[14]=l(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[10]||(e[10]=[l("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=l("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[15]||(e[15]=[l("LCTT",-1)])]),_:1}),e[18]||(e[18]=l(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:p(()=>[...e[16]||(e[16]=[l("Linux中國",-1)])]),_:1}),e[19]||(e[19]=l(" 榮譽推出",-1))])])}const T=i(u,[["render",m]]);export{O as __pageData,T as default};
